css:
.d-filter-url-state{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-filter-url-state *,.d-filter-url-state *::before,.d-filter-url-state *::after{box-sizing:border-box}
.d-filter-url-state [hidden]{display:none!important}
.d-filter-url-state .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-filter-url-state .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-filter-url-state label{display:block;margin:8px 0}
.d-filter-url-state input,.d-filter-url-state select,.d-filter-url-state textarea,.d-filter-url-state button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-filter-url-state input:not([type=checkbox]):not([type=radio]),.d-filter-url-state select,.d-filter-url-state textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-filter-url-state button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-filter-url-state button:disabled{opacity:.5;cursor:default}
.d-filter-url-state :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-filter-url-state [aria-invalid=true]{border-color:var(--warn)!important}
.d-filter-url-state .d-scroll{max-width:100%;overflow:auto}
.d-filter-url-state table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-filter-url-state th,.d-filter-url-state td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-filter-url-state caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-filter-url-state progress{width:100%;accent-color:var(--ink)}
.d-filter-url-state pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-filter-url-state h3,.d-filter-url-state p{margin:8px 0}
.d-filter-url-state [aria-pressed=true],.d-filter-url-state [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-filter-url-state .d-grow{flex:1;min-width:100px}
.d-filter-url-state summary{cursor:pointer;padding:6px 0}
.d-filter-url-state ul,.d-filter-url-state ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{const select=q('[data-filter]'),allowed=['all','pending','done'];const stored=new URL(location.href).searchParams.get('asset-status');select.value=allowed.includes(stored)?stored:'all';const draw=write=>{qa('[data-status]').forEach(item=>item.hidden=select.value!=='all'&&item.dataset.status!==select.value);if(write){const url=new URL(location.href);if(select.value==='all')url.searchParams.delete('asset-status');else url.searchParams.set('asset-status',select.value);try{history.replaceState(history.state,'',url);}catch{say('此预览地址不能写入参数；筛选仍可使用');return;}}say('当前：'+select.selectedOptions[0].textContent);};select.onchange=()=>draw(true);q('[data-reset]').onclick=()=>{select.value='all';draw(true);};draw(false);})(root, q, qa, say);
}
